<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { justifications, justificationLabel } from '../assessmentReasons'
import AnalysisPanel from './AnalysisPanel.vue'
import RescoreEditor from './RescoreEditor.vue'
import type { AssessmentDraft, Finding, Me, RescoreProposal } from '../types'

const props = defineProps<{ finding: Finding; draft: AssessmentDraft; me: Me; busy: boolean; error: string; notice: string; power: boolean; canApprove: boolean; index: number; loaded: number; previous: boolean; next: boolean }>()
const emit = defineEmits<{ close: []; move: [delta: number]; refresh: []; 'update:draft': [draft: AssessmentDraft]; submit: [advance: boolean]; approve: [requestChanges: boolean, advance: boolean] }>()
const descriptions = computed(() => {
  const items: { id: string; source: string; text: string }[] = []
  for (const observation of props.finding.observations) {
    const advisory = observation.advisory as Record<string, unknown> | undefined
    if (typeof advisory?.description === 'string' && advisory.description && !items.some(item => item.text === advisory.description)) items.push({ id: String(observation.id), source: String(observation.source), text: advisory.description })
  }
  if (props.finding.description && !items.some(item => item.text === props.finding.description)) items.unshift({ id: 'primary', source: 'Primary advisory', text: props.finding.description })
  return items
})
const descriptionId = ref('')
const description = computed(() => descriptions.value.find(item => item.id === descriptionId.value) || descriptions.value.find(item => item.text === props.finding.description) || descriptions.value[0])
const roomy = ref(descriptions.value.some(item => item.text.length > 1200))
watch(() => description.value?.text, text => { if (text && text.length > 1200) roomy.value = true })
const justificationReady = computed(() => props.draft.state !== 'not_affected' || Boolean(props.draft.justification && Object.hasOwn(justifications, props.draft.justification)))
const tab = ref('assessment'), editing = ref(false), step = ref(0)
const scorePreview = ref<RescoreProposal | null>(null), reviewConfirmed = ref(false)
const tabs = [['assessment', 'Assessment & review'], ['analysis', 'Analysis'], ['history', 'Evidence & history']]
const tabLabels: Record<string, string> = { assessment: 'Assessment', analysis: 'Analysis', history: 'History' }
const latest = computed(() => props.finding.decisions[0])
const canSubmit = computed(() => !props.busy && props.draft.rationale.trim() && justificationReady.value && (!props.draft.rescoring || props.draft.rescoring.preview_digest))
const showForm = computed(() => props.finding.capabilities.includes('assess') && (editing.value || (!latest.value && !props.canApprove) || ['needs_revalidation', 'changes_requested'].includes(props.finding.lifecycle)))
const steps = computed(() => showForm.value ? ['Applicability', 'Severity', 'Confirm'] : ['Assessment', 'Confirm'])
const lastStep = computed(() => steps.value.length - 1)
const decisionReady = computed(() => Boolean(props.draft.rationale.trim()) && justificationReady.value)
const scoreReady = computed(() => !props.draft.rescoring || Boolean(props.draft.rescoring.preview_digest))
const canContinue = computed(() => !props.busy && (!showForm.value || (step.value === 0 ? decisionReady.value : scoreReady.value)))
const evidenceOpen = ref(props.finding.conflicting_scores || props.finding.stale_evidence || props.finding.lifecycle === 'needs_revalidation')
const furthest = ref(0), stageLabel = ref<HTMLElement | null>(null)
watch(step, async () => { await nextTick(); stageLabel.value?.focus(); stageLabel.value?.closest('.review-content')?.scrollTo({ top: 0 }) })
watch(() => props.finding.lifecycle, value => { if (['approved', 'changes_requested'].includes(value)) { step.value = 0; furthest.value = 0 } })
function goStep(value: number) { step.value = value; furthest.value = Math.max(furthest.value, value) }
function revise() { editing.value = true; furthest.value = 0; step.value = 0 }
watch(showForm, value => { if (!value) { step.value = 0; furthest.value = 0 } })
watch(() => props.finding.state_version, () => { reviewConfirmed.value = false })
watch(() => latest.value?.id, () => { editing.value = false; step.value = 0; furthest.value = 0 })
const names: Record<string, string> = { open: 'Needs analysis', ready: 'Ready for approval', approved: 'Approved', needs_revalidation: 'Evidence changed', changes_requested: 'Changes requested', affected: 'Affected', not_affected: 'Not affected', under_investigation: 'Under investigation', fixed: 'Fixed' }
const label = (state: string) => names[state] || state.replaceAll('_', ' ')
const score = (value: number | null) => value === null ? 'Unknown' : value.toFixed(1)
function update(field: 'state' | 'rationale', value: string) { emit('update:draft', { ...props.draft, [field]: value, justification: field === 'state' && value !== 'not_affected' ? null : props.draft.justification }) }
function useProposal(state: string, rationale: string) { tab.value = 'assessment'; revise(); emit('update:draft', { ...props.draft, state, rationale, justification: state === 'not_affected' ? props.draft.justification : null }) }
watch(() => props.finding.id, () => { tab.value = 'assessment'; editing.value = false })
</script>
<template>
  <div class="overlay review-overlay" @click.self="!busy && emit('close')"><section class="inspector finding-workspace" :class="{ roomy }" role="dialog" aria-modal="true" aria-labelledby="finding-title">
    <div class="inspector-header compact-header"><button class="sheet-close" aria-label="Close finding" :disabled="busy" @click="emit('close')">×</button><div class="sheet-identity"><h1 id="finding-title">{{ finding.identifier }}</h1><p>{{ finding.project }} · {{ finding.release }} · {{ finding.component }} {{ finding.component_version }}</p></div><div class="sheet-queue"><button :aria-label="roomy ? 'Use compact view' : 'Expand review'" :title="roomy ? 'Use compact view' : 'Expand review'" :aria-pressed="roomy" @click="roomy = !roomy">{{ roomy ? '↙' : '↗' }}</button><span>{{ index >= 0 ? `${index + 1}/${loaded}` : 'Outside queue' }}</span><button aria-label="Previous finding" title="Previous finding" :disabled="busy || !previous" @click="emit('move', -1)">‹</button><button aria-label="Next finding" title="Next finding" :disabled="busy || !next" @click="emit('move', 1)">›</button></div></div>
    <div class="review-navigation"><div class="review-tabs" role="tablist" aria-label="Review sections"><button v-for="[key, name] in tabs" :id="`review-tab-${key}`" :key="key" role="tab" :aria-label="name" :aria-selected="tab === key" :aria-controls="`review-panel-${key}`" :tabindex="tab === key ? 0 : -1" :class="{ current: tab === key }" @click="tab = key!" @keydown.right.prevent="tab = tabs[(tabs.findIndex(item => item[0] === tab) + 1) % tabs.length]![0]!; ($event.target as HTMLElement).parentElement?.querySelector<HTMLElement>(`#review-tab-${tab}`)?.focus()" @keydown.left.prevent="tab = tabs[(tabs.findIndex(item => item[0] === tab) + tabs.length - 1) % tabs.length]![0]!; ($event.target as HTMLElement).parentElement?.querySelector<HTMLElement>(`#review-tab-${tab}`)?.focus()">{{ tabLabels[key!] }}</button></div></div>
    <div class="inspector-content review-content">
      <p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="notice" class="message success" role="status">{{ notice }}</p>
      <div v-show="tab === 'assessment'" id="review-panel-assessment" role="tabpanel" aria-labelledby="review-tab-assessment">
        <div class="review-sheet">          <aside class="evidence-column" :class="{ expanded: evidenceOpen }" aria-label="Finding evidence"><button class="mobile-evidence-toggle" :aria-expanded="evidenceOpen" @click="evidenceOpen = !evidenceOpen">Evidence · {{ score(finding.original_score) }} <span>{{ evidenceOpen ? 'Hide' : 'Show' }}</span></button><div class="evidence-body">
            <div class="review-summary"><span class="badge" :class="finding.lifecycle">{{ label(finding.lifecycle) }}</span><div><span class="hint">Original CVSS</span><strong class="score" :class="{ high: (finding.original_score || 0) >= 7 }">{{ score(finding.original_score) }}</strong></div><div v-if="finding.adopted_rescoring"><span class="hint">Approved contextual</span><strong>{{ score(finding.effective_score) }}</strong></div></div>
            <section class="review-section"><h2>Vulnerability</h2><label v-if="descriptions.length > 1" class="description-source">Description source <select :value="description?.id" @change="descriptionId = ($event.target as HTMLSelectElement).value"><option v-for="item in descriptions" :key="item.id" :value="item.id">{{ item.source }}</option></select></label><p class="finding-description">{{ description?.text || 'No advisory description supplied. Review the source evidence.' }}</p><p v-if="finding.lifecycle === 'needs_revalidation'" class="warning">Evidence changed since the last decision. Review the changes and submit a new assessment.</p><p v-if="finding.conflicting_scores" class="warning">Sources disagree on the original score. Review the Base assertions before rescoring or exporting.</p><p v-if="finding.stale_evidence" class="warning">Source evidence is older than 30 days. Check whether it still applies.</p></section>
            <details v-if="latest" class="evidence-assessment"><summary>Recorded assessment · {{ label(latest.state) }}</summary><p v-if="latest.state === 'not_affected'" class="hint">{{ justificationLabel(latest.details.justification) }}</p><p class="rationale-text">{{ latest.rationale }}</p><p class="hint">{{ latest.author_name || 'Recorded analyst' }}</p><p v-if="finding.proposed_rescoring" class="rationale-text">{{ finding.proposed_rescoring.rationale }}</p></details><section class="review-section"><h2>Evidence at a glance</h2><ul class="evidence-sources"><li v-for="observation in finding.observations" :key="String(observation.id)"><strong>{{ observation.source }}</strong><span class="hint">SBOM source observation</span></li><li v-for="record in finding.evidence" :key="String(record.id)"><strong>{{ record.source }}</strong><span class="hint">{{ String(record.kind || 'Additional evidence').replaceAll('-', ' ') }}</span></li></ul><p v-if="!finding.observations.length && !finding.evidence.length" class="hint">No source evidence available.</p><details :open="power"><summary>Original CVSS vectors and package coordinate</summary><p v-for="base in finding.original_vectors" :key="base.vector" class="vector-line"><strong>CVSS {{ base.version }} · {{ base.score }}</strong><code>{{ base.vector }}</code></p><code class="vector-line">{{ finding.purl || 'No PURL supplied' }}</code></details></section>
            <section v-for="(imported, index) in finding.imported_assessments" :key="index" class="review-section"><h2>Imported DT assessment</h2><p class="hint">{{ imported.source }} · {{ imported.format === 'plain-dt' ? 'Legacy documentation without DTVP metadata' : 'Previous DTVP documentation' }}. Imported history is separate from DTVP approval.</p><p v-if="imported.pending_review || imported.conflicting" class="warning">{{ imported.conflicting ? 'Imported team decisions conflict.' : 'Source assessment is pending review.' }}</p><p v-if="imported.suppressed" class="warning">Suppressed in the source. Retained for review.</p><article v-for="(record, position) in imported.current_records" :key="position"><strong>{{ record.team }} · {{ record.state ? label(record.state) : 'Applicability not recorded' }}</strong><p v-if="record.state === 'not_affected'" class="hint">{{ justificationLabel(record.justification) }}</p><p class="rationale-text">{{ record.rationale || 'No rationale recorded.' }}</p><small>{{ record.assessor ? `Source assessor: ${record.assessor}` : 'Assessor not recorded' }}{{ record.reviewer ? ` · Source reviewer: ${record.reviewer}` : '' }}</small><p v-if="record.rescored_score !== null" class="hint">Legacy contextual score: {{ record.rescored_score }}. Original Base severity remains unchanged.</p><p v-if="record.ssvc_priority" class="hint">Imported SSVC priority: {{ record.ssvc_priority }}</p></article></section>
            <section v-for="record in finding.evidence.filter(record => record.kind === 'contextual-assessment')" :key="String(record.id)" class="review-section"><h2>{{ record.source === 'vscorer' ? 'VScorer contextual assessment' : 'Contextual assessment' }}</h2><p v-if="typeof record.environmental_score === 'number'">Proposed Environmental score: <strong>{{ record.environmental_score.toFixed(1) }}</strong></p><p v-if="typeof record.rationale === 'string'" class="rationale-text">{{ record.rationale }}</p><p class="hint">Provider evidence requires explicit adoption and independent DTVP approval.</p></section>
          </div></aside>
<div class="workflow-pane">        <nav class="assessment-steps" aria-label="Assessment progress"><button v-for="(name, index) in steps" :key="name" :aria-current="step === index ? 'step' : undefined" :disabled="busy || index > furthest" @click="goStep(index)"><span class="step-dot">{{ index < step ? '✓' : index + 1 }}</span>{{ name }}</button></nav>
<div ref="stageLabel" tabindex="-1" class="guided-stage" aria-label="Current assessment task" :data-step="step">          <section class="assessment-column">
            <p v-if="!latest && !showForm" class="hint">No assessment has been submitted yet.</p><section v-if="latest && !showForm && step === 0" class="assessment-summary"><h2>Latest assessment</h2><strong>{{ label(latest.state) }}</strong><p v-if="latest.state === 'not_affected'" class="justification">{{ justificationLabel(latest.details.justification) }}</p><p class="rationale-text">{{ latest.rationale }}</p><p class="hint">{{ latest.author_name || 'Recorded analyst' }} · {{ new Date(latest.created_at).toLocaleString() }} · {{ finding.approval && finding.lifecycle === 'approved' ? 'Reviewed and approved' : finding.lifecycle === 'needs_revalidation' ? 'Revalidation required' : 'Awaiting review' }}</p><section v-if="finding.proposed_rescoring" class="score-preview"><h3>{{ finding.adopted_rescoring ? 'Approved contextual score' : 'Proposed contextual score' }}</h3><p>CVSS {{ finding.proposed_rescoring.version }} · Original {{ finding.proposed_rescoring.base_score.toFixed(1) }} → {{ finding.proposed_rescoring.score.toFixed(1) }}</p><p class="rationale-text">{{ finding.proposed_rescoring.rationale }}</p><details><summary>Contextual vector</summary><code class="vector-line">{{ finding.proposed_rescoring.vector }}</code></details></section></section>

            <button v-if="finding.capabilities.includes('assess') && latest && !showForm" :disabled="busy" @click="revise">Revise this assessment</button>
            <form v-if="showForm" @submit.prevent="step === lastStep && canSubmit && emit('submit', false)">
              <div v-show="step === 0"><h2>Your assessment</h2><label>Applicability <select :value="draft.state" :disabled="busy" @change="update('state', ($event.target as HTMLSelectElement).value)"><option value="under_investigation">Under investigation</option><option value="affected">Affected</option><option value="not_affected">Not affected</option><option value="fixed">Fixed</option></select></label><label v-if="draft.state === 'not_affected'">Why not affected? <select :value="draft.justification || ''" :disabled="busy" @change="emit('update:draft', { ...draft, justification: ($event.target as HTMLSelectElement).value || null })"><option value="">Select a reason</option><option v-for="(name, key) in justifications" :key="key" :value="key">{{ name }}</option></select></label><label>Reason and evidence <textarea :value="draft.rationale" rows="4" maxlength="6000" :disabled="busy" placeholder="Record the decisive evidence and next action." @input="update('rationale', ($event.target as HTMLTextAreaElement).value)"></textarea></label></div>
              <div v-show="step === 1"><h2>Contextual severity</h2><RescoreEditor :finding="finding" :state="draft.state" :model-value="draft.rescoring" :disabled="busy" :assessment-rationale="draft.rationale" @preview="scorePreview = $event" @update:model-value="value => emit('update:draft', { ...draft, rescoring: value })" /></div>
              <div v-if="step === lastStep" class="confirmation"><h2>Ready for independent review</h2><dl><dt>Applicability</dt><dd>{{ label(draft.state) }}</dd><template v-if="draft.state === 'not_affected'"><dt>Why not affected</dt><dd>{{ justificationLabel(draft.justification) }}</dd></template><dt>Reason and evidence</dt><dd class="rationale-text">{{ draft.rationale }}</dd><dt>Severity</dt><dd>{{ draft.rescoring ? `Original ${score(finding.original_score)} → Proposed ${scorePreview ? score(scorePreview.score) : 'Preview required'}` : `Original score ${score(finding.original_score)} retained` }}</dd></dl><p v-if="draft.rescoring" class="rationale-text">{{ draft.rescoring.rationale }}</p><p v-if="!canSubmit" class="warning">Complete the rationale and refresh the scoring preview before submitting.</p></div>
            </form>
            <section v-if="latest && !showForm && step === lastStep" class="confirmation"><h2>Confirm review</h2><p v-if="latest.state === 'not_affected'">{{ justificationLabel(latest.details.justification) }}</p><p>{{ label(latest.state) }} · Original {{ score(finding.original_score) }}<template v-if="finding.proposed_rescoring"> → Proposed {{ score(finding.proposed_rescoring.score) }}</template></p></section><label v-if="canApprove && !editing && step === lastStep" class="review-check"><input v-model="reviewConfirmed" type="checkbox" :disabled="busy"><span>I checked applicability, evidence and the proposed score.</span></label><p v-else-if="finding.lifecycle === 'ready' && latest?.author_id === me.id" class="hint">A different reviewer must approve your assessment.</p>
          </section></div></div></div>
      </div>
      <div v-show="tab === 'analysis'" id="review-panel-analysis" role="tabpanel" aria-labelledby="review-tab-analysis"><AnalysisPanel :key="finding.id" :finding-id="finding.id" :state-version="finding.state_version" :evidence-revision="finding.evidence_revision" :enabled="me.agentyzer.enabled" :mode="me.agentyzer.mode" :can-run="finding.capabilities.includes('evidence')" :can-assess="finding.capabilities.includes('assess')" @refresh="emit('refresh')" @proposal="useProposal" /></div>
      <div v-show="tab === 'history'" id="review-panel-history" role="tabpanel" aria-labelledby="review-tab-history"><h2>Evidence and decision history</h2><p class="hint">Full provider assertions and prior decisions remain available for detailed review.</p><section v-for="decision in finding.decisions" :key="decision.id" class="decision-record"><h3>{{ label(decision.state) }} · {{ new Date(decision.created_at).toLocaleString() }}</h3><p v-if="decision.state === 'not_affected'" class="hint">{{ justificationLabel(decision.details.justification) }}</p><p class="rationale-text">{{ decision.rationale }}</p><p class="hint">Evidence revision {{ decision.evidence_revision }} · {{ label(decision.status) }}</p></section><details :open="power"><summary>Technical evidence and history</summary><h3>Package coordinate</h3><code>{{ finding.purl || 'No PURL supplied' }}</code><h3>Source observations</h3><pre>{{ JSON.stringify(finding.observations, null, 2) }}</pre><h3>Contextual evidence</h3><pre>{{ JSON.stringify(finding.evidence, null, 2) }}</pre><h3>Decision history</h3><pre>{{ JSON.stringify(finding.decisions, null, 2) }}</pre></details></div>

    </div>
    <footer class="guided-footer"><template v-if="tab === 'assessment'"><button :disabled="busy || step === 0" @click="goStep(step - 1)">Back</button><span class="draft-status">{{ showForm ? 'Draft saved locally' : label(finding.lifecycle) }}</span><button v-if="step < lastStep" class="primary" :aria-label="showForm && step === 0 ? 'Continue to severity' : 'Review and confirm'" :disabled="!canContinue" @click="goStep(step + 1)">Continue <span aria-hidden="true">→</span></button><div v-else-if="showForm" class="approval-actions"><button class="primary" aria-label="Submit assessment" :disabled="!canSubmit" @click="emit('submit', false)">Submit</button><button aria-label="Submit and next" :disabled="!canSubmit" @click="emit('submit', true)">Submit & next</button></div><div v-else-if="canApprove && !editing" class="approval-actions"><button :disabled="busy" @click="emit('approve', true, false)">Request changes</button><button class="primary" aria-label="Approve decision" :disabled="busy || !reviewConfirmed" @click="emit('approve', false, false)">Approve</button><button aria-label="Approve and next" :disabled="busy || !reviewConfirmed" @click="emit('approve', false, true)">Approve & next</button></div></template><button class="sheet-refresh" aria-label="Refresh evidence" title="Refresh evidence" :disabled="busy" @click="emit('refresh')">↻</button></footer>
  </section></div>
</template>
